#!/usr/bin/env python3
"""Verify static initializer evidence against unchanged captured SBF bytes."""
from pathlib import Path
import hashlib,json,struct
from solders.pubkey import Pubkey
import extract
ROOT=Path(__file__).resolve().parent; REPO=extract.REPO;b=extract.b
assert hashlib.sha256(b).hexdigest()=='4f2955d0f6b40cc9ff7daa18ccad7d19119ba1249759f4e7e3bb691beee6b35e'
admin=Pubkey.from_bytes(b[0xc36e0:0xc3700]);assert str(admin)=='8LWu7QM2dGR1G8nKDHthckea57bkCzXyBTAKPJUBDHo8'
idl=json.loads((REPO/'evidence/upstream/pump_fees.json').read_text());instruction=next(x for x in idl['instructions'] if x['name']=='initialize_fee_config');event=next(x for x in idl['events'] if x['name']=='InitializeFeeConfigEvent');event_type=next(x for x in idl['types'] if x['name']=='InitializeFeeConfigEvent')
assert bytes(instruction['discriminator'])==hashlib.sha256(b'global:initialize_fee_config').digest()[:8]
assert bytes(event['discriminator'])==hashlib.sha256(b'event:InitializeFeeConfigEvent').digest()[:8]==bytes.fromhex('598af4e60a38e27e')
funcs={name:extract.dump(name,start) for name,start in {'wrapper':0x96b90,'accounts':0x48378,'account-init':0x49bd0,'handler':0x14308,'exit':0x5e80,'signer':0xacb80,'fee-deserialize':0x3ecf0,'unchecked-account-deserialize':0x47d0,'clock':0xb10f0,'custom-error':0x46c58}.items()}
windows=[('signer-required',0xacb90,0xacbc0,'AccountInfo.is_signer at 0x28; false constructs Anchor3010'),('fee-config-pda',0x48ad0,0x48b68,'b"fee_config" length10 + config_program_id key32; find_program_address'),('init-space-rent',0x49c20,0x49c38,'Minimum rent requested for0x9d0=2512bytes'),('create-account-space',0x4a3c8,0x4a3e0,'Systemcreatehelper passedspace0x9d0=2512bytes'),('fee-config-mut',0x49050,0x49068,'Initialized fee_config is_writable checked'),('admin-mut',0x49268,0x492a0,'adminis_writable required,error2000'),('admin-address',0x49608,0x49650,'32-byteconstantkeyat0xc36e0comparedtoadmin'),('admin-error',0x49898,0x498b8,'Adminmismatchcustomenumindex1=>6001'),('custom-error-code',0x46de0,0x46df0,'Customindex+6000'),('fee-config-bump-write',0x14318,0x14330,'canonicalbumpcontext+0x20toFeeConfigmemory+0x80'),('admin-key-write',0x14330,0x14380,'adminAccountInfo.keytoFeeConfigmemory+0x30..0x50'),('event-clock',0x14380,0x143a8,'Clock::get via0xb10f0,errorpropagates'),('event-discriminator',0x145a8,0x145c0,'InitializeFeeConfigEventdiscriminator598af4e60a38e27e'),('event-log-length',0x14648,0x14678,'80-byteeventpayloadlogged'),('event-cpi-prefix',0x14988,0x149a0,'AnchorCPIeventprefixe445a52e51cb9a1d'),('event-cpi-seed',0x14c08,0x14c48,'__event_authorityseedlength17andcanonicalbump'),('event-cpi-invoke',0x14c90,0x14ca8,'SelfCPIwithoneevent-authorityaccountandonesignerseedset'),('base-size-minimum',0x3ecf8,0x3ed18,'FeeConfigdeserializerrequires2504bytesafter8-bytediscriminator;stablethreshold4065afterdiscriminator'),('legacy-extra-defaults',0x3eee0,0x3ef10,'Legacy-sizebranchsetsstable_fee_tiersemptyandexotic_flat_feeszero')]
evidence={'scope':'Static evidence only; no program execution. Raw offsets are ELF file offsets; context/struct memory offsets are not serialized offsets.','binary':{'path':'evidence/original/pump_fees/deployed.so','sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)},'idl':{'path':'evidence/upstream/pump_fees.json','sha256':hashlib.sha256((REPO/'evidence/upstream/pump_fees.json').read_bytes()).hexdigest(),'instruction':instruction,'event':event,'event_type':event_type},'fixed_admin':{'pubkey':str(admin),'file_offset':0xc36e0,'bytes_hex':bytes(admin).hex()},'functions':funcs,'windows':[{'name':name,'start':lo,'end':hi,'bytes_hex':b[lo:hi].hex(),'sha256':hashlib.sha256(b[lo:hi]).hexdigest(),'claim':claim} for name,lo,hi,claim in windows]}
(ROOT/'static-evidence.json').write_text(json.dumps(evidence,indent=2)+'\n')
print(json.dumps({'captured_sha256':evidence['binary']['sha256'],'fixed_admin':str(admin),'functions':len(funcs),'evidence_windows':len(windows),'initializer_accounts':len(instruction['accounts']),'instruction_args':instruction['args']},indent=2))
